const databaseName = "OnlineSurvey";
const authDatabaseName = "OnlineSurvey";
const targetDb = db.getSiblingDB(databaseName);
const targetAuthDb = db.getSiblingDB(authDatabaseName);

const surveys = EJSON.parse(Buffer.from("", "base64").toString("utf8"));
const responses = EJSON.parse(Buffer.from("", "base64").toString("utf8"));
const surveyIndexes = EJSON.parse(Buffer.from("", "base64").toString("utf8"));
const responseIndexes = EJSON.parse(Buffer.from("", "base64").toString("utf8"));
const admins = EJSON.parse(Buffer.from("", "base64").toString("utf8"));
const adminIndexes = EJSON.parse(Buffer.from("", "base64").toString("utf8"));

targetDb.surveys.drop();
targetDb.responses.drop();
targetAuthDb.admins.drop();

targetDb.createCollection("surveys");
targetDb.createCollection("responses");
targetAuthDb.createCollection("admins");

if (surveys.length > 0) {
    targetDb.surveys.insertMany(surveys);
}

if (responses.length > 0) {
    targetDb.responses.insertMany(responses);
}

if (admins.length > 0) {
    targetAuthDb.admins.insertMany(admins);
}

function restoreIndexes(collection, specs) {
    for (const spec of specs) {
        if (spec.name === "_id_") continue;

        const options = { name: spec.name };
        for (const optionName of [
            "unique",
            "sparse",
            "expireAfterSeconds",
            "partialFilterExpression",
            "collation",
            "hidden"
        ]) {
            if (spec[optionName] !== undefined) {
                options[optionName] = spec[optionName];
            }
        }

        collection.createIndex(spec.key, options);
    }
}

restoreIndexes(targetDb.surveys, surveyIndexes);
restoreIndexes(targetDb.responses, responseIndexes);
restoreIndexes(targetAuthDb.admins, adminIndexes);

print("Khoi phuc database thanh cong:");
print("- Database: " + databaseName);
print("- surveys: " + targetDb.surveys.countDocuments());
print("- responses: " + targetDb.responses.countDocuments());
print("- survey indexes: " + targetDb.surveys.getIndexes().length);
print("- response indexes: " + targetDb.responses.getIndexes().length);
print("- Auth database: " + authDatabaseName);
print("- admins: " + targetAuthDb.admins.countDocuments());
print("- admin indexes: " + targetAuthDb.admins.getIndexes().length);

